/* From Uiverse.io by mi-series - Tags: form, register, registration form, registration */
.__UIV_SCOPE__ .container {
  position: relative;
  max-width: 500px;
  width: 100%;
  background: #FCEDDA;
  padding: 25px;
  border-radius: 8px;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .container header {
  font-size: 1.2rem;
  color: #000;
  font-weight: 600;
  text-align: center;
}

.__UIV_SCOPE__ .container .form {
  margin-top: 15px;
}

.__UIV_SCOPE__ .form .input-box {
  width: 100%;
  margin-top: 10px;
}

.__UIV_SCOPE__ .input-box label {
  color: #000;
}

.__UIV_SCOPE__ .form :where(.input-box input, .select-box) {
  position: relative;
  height: 35px;
  width: 100%;
  outline: none;
  font-size: 1rem;
  color: #808080;
  margin-top: 5px;
  border: 1px solid #EE4E34;
  border-radius: 6px;
  padding: 0 15px;
  background: #FCEDDA;
}

.__UIV_SCOPE__ .input-box input:focus {
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .form .column {
  display: flex;
  column-gap: 15px;
}

.__UIV_SCOPE__ .form .gender-box {
  margin-top: 10px;
}

.__UIV_SCOPE__ .form :where(.gender-option, .gender) {
  display: flex;
  align-items: center;
  column-gap: 50px;
  flex-wrap: wrap;
}

.__UIV_SCOPE__ .form .gender {
  column-gap: 5px;
}

.__UIV_SCOPE__ .gender input {
  accent-color: #EE4E34;
}

.__UIV_SCOPE__ .form :where(.gender input, .gender label) {
  cursor: pointer;
}

.__UIV_SCOPE__ .gender label {
  color: #000;
}

.__UIV_SCOPE__ .address :where(input, .select-box) {
  margin-top: 10px;
}

.__UIV_SCOPE__ .select-box select {
  height: 100%;
  width: 100%;
  outline: none;
  border: none;
  color: #808080;
  font-size: 1rem;
  background: #FCEDDA;
}

.__UIV_SCOPE__ .form button {
  height: 40px;
  width: 100%;
  color: #000;
  font-size: 1rem;
  font-weight: 400;
  margin-top: 15px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  background: #EE4E34;
}

.__UIV_SCOPE__ .form button:hover {
  background: #EE3E34;
}
